-- 103 (v1.35.0) finance phase 24.
--
--   rec_purchase          renewable energy certificates (REC, 1 MWh each) bought — for a site or the portfolio — and
--                         retired against a month's charging
--   carbon_credit         carbon credits (tCO2e) generated by a period's avoided emissions: estimated, verified, issued
--   carbon_credit_sale    credits sold: buyer, tonnes, price
--   insurance_policy      a policy per site, charger or the organisation: insurer, cover, premium, excess, term; the
--                         premium paid is prepaid and amortised over the term
--   insurance_claim       a claim under a policy (damage, theft, liability): the loss, the excess, what was recovered
--   compliance_task       a statutory or audit deadline: authority, due date, recurrence, owner, status, reminders
--   compliance_evidence   files attached to a task or to an auditor's request (up to 5 MB)
--   pbc_request           the auditor's requests (prepared by client): item, due date, owner, status
--   finance_org_settings  .carbon {gridKgPerKwh, iceKgPerKwh}
--   gl_entry.source       gains 'carbon', 'insurance'
--
-- Additive. Rollback: db/rollback/103_down.sql.

ALTER TABLE finance_org_settings ADD COLUMN IF NOT EXISTS carbon JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS rec_purchase (
  id               BIGSERIAL PRIMARY KEY,
  org_id           UUID NOT NULL REFERENCES organisation(id),
  site_id          UUID REFERENCES site(id),
  registry         TEXT NOT NULL,
  reference        TEXT,
  vintage          INT NOT NULL CHECK (vintage BETWEEN 2000 AND 2100),
  mwh              NUMERIC(14,3) NOT NULL CHECK (mwh > 0),
  currency         TEXT NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  price_minor      BIGINT NOT NULL CHECK (price_minor >= 0),
  bought_on        DATE NOT NULL,
  cash_account_id  BIGINT REFERENCES cash_account(id),
  retired_month    TEXT CHECK (retired_month ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  retired_on       DATE,
  voided_at        TIMESTAMPTZ,
  created_by       UUID REFERENCES app_user(id),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS carbon_credit (
  id            BIGSERIAL PRIMARY KEY,
  org_id        UUID NOT NULL REFERENCES organisation(id),
  period_from   TEXT NOT NULL CHECK (period_from ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  period_to     TEXT NOT NULL CHECK (period_to ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  tonnes        NUMERIC(14,3) NOT NULL CHECK (tonnes >= 0),
  status        TEXT NOT NULL DEFAULT 'estimated' CHECK (status IN ('estimated', 'verified', 'issued', 'void')),
  standard      TEXT,
  serial        TEXT,
  issued_on     DATE,
  note          TEXT,
  created_by    UUID REFERENCES app_user(id),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS carbon_credit_sale (
  id               BIGSERIAL PRIMARY KEY,
  org_id           UUID NOT NULL REFERENCES organisation(id),
  credit_id        BIGINT NOT NULL REFERENCES carbon_credit(id),
  buyer            TEXT NOT NULL,
  tonnes           NUMERIC(14,3) NOT NULL CHECK (tonnes > 0),
  currency         TEXT NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  amount_minor     BIGINT NOT NULL CHECK (amount_minor >= 0),
  sold_on          DATE NOT NULL,
  cash_account_id  BIGINT REFERENCES cash_account(id),
  reference        TEXT,
  voided_at        TIMESTAMPTZ,
  created_by       UUID REFERENCES app_user(id),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS insurance_policy (
  id               BIGSERIAL PRIMARY KEY,
  org_id           UUID NOT NULL REFERENCES organisation(id),
  insurer          TEXT NOT NULL,
  policy_no        TEXT NOT NULL,
  kind             TEXT NOT NULL CHECK (kind IN ('property', 'equipment', 'liability', 'business_interruption', 'vehicle', 'other')),
  site_id          UUID REFERENCES site(id),
  charge_point_id  UUID REFERENCES charge_point(id),
  currency         TEXT NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  cover_minor      BIGINT NOT NULL CHECK (cover_minor > 0),
  premium_minor    BIGINT NOT NULL CHECK (premium_minor >= 0),
  excess_minor     BIGINT NOT NULL DEFAULT 0 CHECK (excess_minor >= 0),
  start_on         DATE NOT NULL,
  end_on           DATE NOT NULL,
  paid_on          DATE,
  cash_account_id  BIGINT REFERENCES cash_account(id),
  status           TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'cancelled')),
  renewed_by       BIGINT REFERENCES insurance_policy(id),
  note             TEXT,
  created_by       UUID REFERENCES app_user(id),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (end_on > start_on),
  UNIQUE (org_id, insurer, policy_no)
);

CREATE TABLE IF NOT EXISTS insurance_claim (
  id               BIGSERIAL PRIMARY KEY,
  org_id           UUID NOT NULL REFERENCES organisation(id),
  policy_id        BIGINT NOT NULL REFERENCES insurance_policy(id),
  number           TEXT NOT NULL,
  kind             TEXT NOT NULL CHECK (kind IN ('damage', 'theft', 'liability', 'interruption', 'other')),
  incident_on      DATE NOT NULL,
  description      TEXT NOT NULL,
  work_order_id    BIGINT REFERENCES work_order(id),
  loss_minor       BIGINT NOT NULL CHECK (loss_minor >= 0),
  status           TEXT NOT NULL DEFAULT 'reported' CHECK (status IN ('reported', 'submitted', 'accepted', 'rejected', 'paid', 'closed')),
  insurer_ref      TEXT,
  settled_minor    BIGINT,
  paid_on          DATE,
  note             TEXT,
  created_by       UUID REFERENCES app_user(id),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (org_id, number)
);

CREATE TABLE IF NOT EXISTS compliance_task (
  id             BIGSERIAL PRIMARY KEY,
  org_id         UUID NOT NULL REFERENCES organisation(id),
  title          TEXT NOT NULL,
  category       TEXT NOT NULL CHECK (category IN ('financial_statements', 'regulator', 'licence', 'corporate', 'tax_other', 'audit', 'other')),
  authority      TEXT,
  due_on         DATE NOT NULL,
  recurrence     TEXT NOT NULL DEFAULT 'none' CHECK (recurrence IN ('none', 'monthly', 'quarterly', 'yearly')),
  owner_id       UUID REFERENCES app_user(id),
  remind_days    INT NOT NULL DEFAULT 14 CHECK (remind_days BETWEEN 0 AND 120),
  status         TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'done', 'waived')),
  done_on        DATE,
  done_by        UUID REFERENCES app_user(id),
  note           TEXT,
  next_id        BIGINT REFERENCES compliance_task(id),
  created_by     UUID REFERENCES app_user(id),
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS pbc_request (
  id            BIGSERIAL PRIMARY KEY,
  org_id        UUID NOT NULL REFERENCES organisation(id),
  audit         TEXT NOT NULL,
  ref           TEXT,
  item          TEXT NOT NULL,
  requested_on  DATE NOT NULL,
  due_on        DATE,
  owner_id      UUID REFERENCES app_user(id),
  status        TEXT NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'in_progress', 'provided', 'accepted')),
  note          TEXT,
  provided_on   DATE,
  created_by    UUID REFERENCES app_user(id),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS compliance_evidence (
  id           BIGSERIAL PRIMARY KEY,
  org_id       UUID NOT NULL REFERENCES organisation(id),
  task_id      BIGINT REFERENCES compliance_task(id),
  pbc_id       BIGINT REFERENCES pbc_request(id),
  filename     TEXT NOT NULL,
  mime         TEXT NOT NULL,
  bytes        INT NOT NULL,
  sha256       TEXT NOT NULL,
  data         BYTEA NOT NULL,
  uploaded_by  UUID REFERENCES app_user(id),
  uploaded_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK ((task_id IS NULL) <> (pbc_id IS NULL)),
  CHECK (bytes <= 5242880)
);

ALTER TABLE gl_entry DROP CONSTRAINT IF EXISTS gl_entry_source_check;
ALTER TABLE gl_entry ADD CONSTRAINT gl_entry_source_check
  CHECK (source IN ('manual', 'gateway', 'assets', 'leases', 'provision', 'bills', 'deposits', 'expenses', 'intercompany', 'reversal', 'payroll', 'customer_deposits', 'projects',
                    'inventory', 'maintenance', 'loans', 'carbon', 'insurance'));

DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['rec_purchase', 'carbon_credit', 'carbon_credit_sale', 'insurance_policy', 'insurance_claim', 'compliance_task', 'pbc_request', 'compliance_evidence'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', t || '_tenant', t);
    EXECUTE format('CREATE POLICY %I ON %I USING (app_rls_bypass() OR org_id = app_current_org()) WITH CHECK (app_rls_bypass() OR org_id = app_current_org())', t || '_tenant', t);
  END LOOP;
END $$;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'plugsure_app') THEN
    GRANT SELECT, INSERT, UPDATE ON rec_purchase, carbon_credit, carbon_credit_sale, insurance_policy, insurance_claim, compliance_task, pbc_request, compliance_evidence TO plugsure_app;
    REVOKE DELETE, TRUNCATE ON rec_purchase, carbon_credit, carbon_credit_sale, insurance_policy, insurance_claim, compliance_task, pbc_request, compliance_evidence FROM plugsure_app;
    GRANT USAGE, SELECT ON SEQUENCE rec_purchase_id_seq, carbon_credit_id_seq, carbon_credit_sale_id_seq, insurance_policy_id_seq, insurance_claim_id_seq, compliance_task_id_seq, pbc_request_id_seq,
      compliance_evidence_id_seq TO plugsure_app;
  END IF;
END $$;
